        },
        {
          "factKey": "laneCrossingEstablished",
          "documentId": "ib-evidence-brief-dev-1-9b5e64c8:statement",
          "quote": "Claimant reports vehicle was stationary at impact and says the other vehicle crossed the center line."
        },
        {
          "factKey": "laneCrossingEstablished",
          "documentId": "ib-evidence-brief-dev-1-9b5e64c8:witness",
          "quote": "Witness reports both vehicles were moving; witness could not see the lane markings. Witness did not identify which vehicle crossed the center line."
        },
        {
          "factKey": "policeAccountIndependent",
          "documentId": "ib-evidence-brief-dev-1-9b5e64c8:manifest",
          "quote": "The police report is an intake summary based on the claimant statement, not an independent eyewitness account."
